<script setup>
import { onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'
const counts=ref([]),selected=ref(null),items=ref([]),loading=ref(true),error=ref('');async function load(){try{const {data,error:e}=await supabase.from('inventory_counts').select('*, profiles(full_name)').eq('status','completed').order('completed_at',{ascending:false});if(e)throw e;counts.value=data}catch{error.value='Zgodovine ni bilo mogoče naložiti.'}finally{loading.value=false}}async function open(c){selected.value=c;const {data,error:e}=await supabase.from('inventory_count_items').select('quantity, products(name,unit)').eq('inventory_count_id',c.id);if(e){error.value='Podrobnosti ni bilo mogoče naložiti.'}else items.value=data}onMounted(load)
</script><template><section class="page"><header><p class="eyebrow">ADMINISTRACIJA</p><h1>Zgodovina popisov</h1></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="center-state">Nalagam zgodovino …</div><template v-else-if="selected"><button class="link" @click="selected=null">← Nazaj na seznam</button><h2>{{new Date(selected.completed_at).toLocaleDateString('sl-SI')}}</h2><p class="muted">Opravil: {{selected.profiles?.full_name || '—'}} · Completed</p><div v-for="i in items" class="list-row"><strong>{{i.products?.name}}</strong><span>{{i.quantity}} {{i.products?.unit}}</span></div></template><button v-else v-for="c in counts" class="list-row button-row" @click="open(c)"><span><strong>{{new Date(c.completed_at).toLocaleDateString('sl-SI')}}</strong><small>opravil: {{c.profiles?.full_name || '—'}}</small></span><span>Completed</span></button></section></template>
